#[test]
fn the_language_filter_isolates_rust_from_typescript() {
    let (_dir, root) = tree(&[
        ("a.rs", "fn alpha() {}\n"),
        ("b.ts", "export function alpha() {}\n"),
    ]);
    let registry = AnalyzerRegistry::new(vec![Arc::new(RustAnalyzer::new()), Arc::new(OtherLanguage)]);
    let run = |language| {
        let request = SearchRequest {
            root: &root,
            query: "alpha",
            exact: false,
            allow_tests: false,
            respect_ignore_files: true,
            language,
        };
        let result = search(&registry, &request).unwrap();
        found(&result, &root).into_iter().map(|row| row.0).collect::<Vec<_>>()
    };
    assert_eq!(run(None), ["a.rs", "b.ts"]);
    assert_eq!(run(Some(Language::Rust)), ["a.rs"]);
    assert_eq!(run(Some(Language::TypeScript)), ["b.ts"]);
    assert_eq!(run(Some(Language::JavaScript)), Vec::<String>::new());
}

/// Claims `.ts` files and makes each one a single block, standing in for the TypeScript analyzer.
struct OtherLanguage;

impl LanguageAnalyzer for OtherLanguage {
    fn languages(&self) -> &[LanguageId] {
        &[LanguageId::TypeScript]
    }
    fn supports(&self, path: &Utf8Path) -> bool {
        path.extension() == Some("ts")
    }
    fn language_for(&self, path: &Utf8Path) -> Option<LanguageId> {
        self.supports(path).then_some(LanguageId::TypeScript)
    }
    fn capabilities(&self, language: LanguageId) -> AnalyzerCapabilities {
        RustAnalyzer::new().capabilities(language)
    }
    fn analyze_with_profile(
        &self,
        path: &Utf8Path,
        source: Box<dyn FnOnce() -> Result<String>>,
        profile: AnalysisProfile,
    ) -> Result<Arc<FileAnalysis>> {
        let text = source()?;
        let block = CodeBlock {
            file: path.to_owned(),
            line_start: 1,
            line_end: 1,
            node_kind: SymbolKind::Function,
            code: text.trim_end().to_owned(),
            symbol_signature: None,
            matched_lines: Vec::new(),
            matched_keywords: Vec::new(),
            parent: None,
        };
