const SEARCH_HEADER: &str = "search[N]{file,lineStart,lineEnd,nodeKind,parent,symbolSignature,snippet,rank,finalScore}:";

/// A project with one Rust file and one TypeScript file that both mention `total_price`.
fn mixed_project() -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    std::fs::create_dir_all(dir.path().join("src")).unwrap();
    std::fs::write(dir.path().join("src/cart.rs"), CART_RS).unwrap();
    std::fs::write(dir.path().join("src/cart.ts"), "export function total_price(): number {\\n  return 1;\\n}\\n").unwrap();
    dir
}

#[cfg(feature = "lang-rust")]
#[test]
fn rust_code_is_searched_as_blocks_and_test_code_only_on_request() {
    let dir = mixed_project();
    let output = monokl_in(dir.path(), &["search", "total_price", "src/cart.rs"]);
    assert!(output.status.success(), "stderr: {}", stderr(&output));
    assert_eq!(
        stdout(&output),
        format!(
            "{}\\n  src/cart.rs,6,9,method,impl Cart,pub fn total_price(&self) -> u32,null,1,4.452186\\n",
            SEARCH_HEADER.replace("[N]", "[1]")
        )
    );

    let output = monokl_in(dir.path(), &["search", "total_price", "src/cart.rs", "--tests"]);
    assert!(output.status.success(), "stderr: {}", stderr(&output));
    assert_eq!(
        stdout(&output),
        format!(
