use std::time::Instant;

use ra_ap_syntax::{Edition, SourceFile, WalkEvent};

// usage: depth <kind> <n>   (kind: mod | paren | neg | block | ty)
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let n: usize = args[2].parse().unwrap();
    let text = match args[1].as_str() {
        "mod" => format!("{}fn leaf() {{}}\n{}", "mod m { ".repeat(n), "}".repeat(n)),
        "paren" => format!("fn f() {{ let x = {}1{}; }}\n", "(".repeat(n), ")".repeat(n)),
        "neg" => format!("fn f() {{ let x = {}1; }}\n", "- ".repeat(n)),
        "block" => format!("fn f() {{ {}1{} }}\n", "{".repeat(n), "}".repeat(n)),
        "ty" => format!("type T = {}u8{};\n", "Vec<".repeat(n), ">".repeat(n)),
        other => panic!("{other}"),
    };
    let stack: usize = std::env::var("STACK_MB").ok().and_then(|s| s.parse().ok()).unwrap_or(512) << 20;
    let handle = std::thread::Builder::new()
        .stack_size(stack)
        .spawn(move || {
            let t = Instant::now();
            let parse = SourceFile::parse(&text, Edition::CURRENT);
            println!("parse {:?}", t.elapsed());
            let t = Instant::now();
            let mut depth = 0usize;
            let mut max = 0usize;
            for event in parse.syntax_node().preorder() {
                match event {
                    WalkEvent::Enter(_) => {
                        depth += 1;
                        max = max.max(depth);
                    }
                    WalkEvent::Leave(_) => depth -= 1,
                }
            }
            println!("depth {max} preorder {:?}", t.elapsed());
            let t = Instant::now();
            let errors = parse.errors().len();
            println!("errors {errors} {:?}", t.elapsed());
            if std::env::var("FORGET").is_ok() {
                std::mem::forget(parse);
            } else {
                drop(parse);
            }
            std::thread::sleep(std::time::Duration::from_millis(500));
            println!("dropped");
        })
        .unwrap();
    handle.join().unwrap();
}

